//#region src/js/setuptrees.ts
/**
* Composable to populate the trees of grade categories
* and items when MyGrades loads. Done as this process
* can be slow.
*/
function usePopulateTrees() {
	const populate = () => {
		return moodleFetch("local_gugrades_get_levelonecategories", {}).then((result) => {
			const activitytree = useActivityTreeStore();
			let promises = [];
			result.categories.forEach((cat) => {
				const catid = cat.id;
				promises.push(moodleFetch("local_gugrades_get_activities", {
					categoryid: catid,
					detailed: true
				}).then((result) => {
					activitytree.trees[catid] = result.activities;
					activitytree.errors[catid] = result.error;
				}).catch((error) => {
					console.error(error);
				}));
			});
			return Promise.all(promises).then(() => {
				activitytree.ready = true;
				console.log("Activity trees preloaded");
			});
		}).catch((error) => {
			console.error(error);
		});
	};
	return { populate };
}
